import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

const fresh = async (t) => {
  const h = await createHost();
  t.after(() => h.__dispose());
  return h;
};

test('place, reserve, confirm', async (t) => {
  const h = await fresh(t);
  assert.deepEqual(await h.place('a', 1), { ok: true });
  assert.deepEqual(await h.order('a'), { status: 'pending', qty: 1 });
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 1);
  assert.equal(msgs[0].from, 'a');
  assert.equal(msgs[0].to, 'inventory');
  assert.equal(msgs[0].action, 'Reserve');
  assert.deepEqual(msgs[0].data, { from: 'a', qty: 1 });
  await h.deliver(msgs[0].id);
  const reply = await h.inFlight();
  assert.deepEqual(reply.map((m) => [m.from, m.to, m.action, m.data]), [['inventory', 'a', 'Reserved', {}]]);
  await h.deliverAll();
  assert.deepEqual(await h.order('a'), { status: 'confirmed', qty: 1 });
  assert.deepEqual(await h.stock(), { available: 0, reserved: 1 });
});

test('refusals', async (t) => {
  const h = await fresh(t);
  assert.equal((await h.place('a', 3)).ok, false);
  assert.equal((await h.place('a', 0)).ok, false);
  assert.equal(await h.order('a'), null);
  assert.equal((await h.cancel('zz')).ok, false);
  assert.deepEqual(await h.place('a', 2), { ok: true });
  assert.equal((await h.place('a', 1)).ok, false);
  assert.deepEqual(await h.order('a'), { status: 'pending', qty: 2 });
  await h.deliverAll();
  assert.deepEqual(await h.order('a'), { status: 'rejected', qty: 2 });
  assert.equal((await h.cancel('a')).ok, false);
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0 });
});

test('restock up to 3', async (t) => {
  const h = await fresh(t);
  assert.deepEqual(await h.restock(), { ok: true });
  assert.deepEqual(await h.restock(), { ok: true });
  assert.equal((await h.restock()).ok, false);
  assert.deepEqual(await h.stock(), { available: 3, reserved: 0 });
});

test('cancel confirmed gives units back', async (t) => {
  const h = await fresh(t);
  await h.place('a', 1);
  await h.deliverAll();
  assert.deepEqual(await h.cancel('a'), { ok: true });
  assert.deepEqual(await h.order('a'), { status: 'cancelled', qty: 1 });
  assert.deepEqual((await h.inFlight()).map((m) => [m.action, m.data]), [['Release', { qty: 1 }]]);
  await h.deliverAll();
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0 });
  assert.equal((await h.cancel('a')).ok, false);
});

test('cancel pending: reserved then released', async (t) => {
  const h = await fresh(t);
  await h.place('a', 1);
  assert.deepEqual(await h.cancel('a'), { ok: true });
  assert.deepEqual(await h.order('a'), { status: 'cancelling', qty: 1 });
  assert.equal((await h.cancel('a')).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.order('a'), { status: 'cancelled', qty: 1 });
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0 });
});

test('cancel pending: out of stock', async (t) => {
  const h = await fresh(t);
  await h.place('a', 2);
  await h.cancel('a');
  await h.deliverAll();
  assert.deepEqual(await h.order('a'), { status: 'cancelled', qty: 2 });
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0 });
});

test('expire confirmed gives units back', async (t) => {
  const h = await fresh(t);
  assert.equal((await h.expire('zz')).ok, false);
  await h.place('a', 1);
  assert.equal((await h.expire('a')).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.expire('a'), { ok: true });
  assert.deepEqual(await h.order('a'), { status: 'expired', qty: 1 });
  assert.equal((await h.expire('a')).ok, false);
  assert.equal((await h.cancel('a')).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0 });
});

test('expire refused for cancelling and cancelled', async (t) => {
  const h = await fresh(t);
  await h.place('a', 1);
  await h.cancel('a');
  assert.equal((await h.expire('a')).ok, false);
  await h.deliverAll();
  assert.equal((await h.expire('a')).ok, false);
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0 });
});

test('two orders race for one unit', async (t) => {
  const h = await fresh(t);
  await h.place('a', 1);
  await h.place('b', 1);
  const msgs = await h.inFlight();
  const b = msgs.find((m) => m.from === 'b');
  await h.deliver(b.id);
  await h.deliverAll();
  assert.equal((await h.order('b')).status, 'confirmed');
  assert.equal((await h.order('a')).status, 'rejected');
  assert.deepEqual(await h.stock(), { available: 0, reserved: 1 });
});

